const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
$('#year').textContent=new Date().getFullYear();
$('.menu-toggle').addEventListener('click',()=>{const open=$('nav').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',String(open));$('.menu-toggle').textContent=open?'Close −':'Menu +'});
$$('nav a').forEach(a=>a.addEventListener('click',()=>{$('nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').textContent='Menu +'}));
$$('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const filter=button.dataset.filter;$$('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});$('.gallery').classList.toggle('filtered',filter!=='all');$$('.shot').forEach(shot=>shot.hidden=filter!=='all'&&!shot.dataset.category.split(' ').includes(filter))}));
let currentPhoto=0;let visiblePhotos=[];function showPhoto(index){currentPhoto=(index+visiblePhotos.length)%visiblePhotos.length;const shot=visiblePhotos[currentPhoto];$('#lightbox-image').src=`assets/${shot.dataset.image}.jpg`;$('#lightbox-image').alt=shot.querySelector('img').alt;$('.lightbox-caption h3').textContent=shot.dataset.title;$('.lightbox-caption p').textContent=`${String(currentPhoto+1).padStart(2,'0')} / ${String(visiblePhotos.length).padStart(2,'0')} — ${shot.dataset.sub}`}
$$('.shot').forEach(shot=>shot.addEventListener('click',()=>{visiblePhotos=$$('.shot').filter(s=>!s.hidden);showPhoto(visiblePhotos.indexOf(shot));$('#lightbox').showModal()}));
$('.photo-prev').addEventListener('click',()=>showPhoto(currentPhoto-1));$('.photo-next').addEventListener('click',()=>showPhoto(currentPhoto+1));document.addEventListener('keydown',e=>{if($('#lightbox').open){if(e.key==='ArrowRight')showPhoto(currentPhoto+1);if(e.key==='ArrowLeft')showPhoto(currentPhoto-1)}});
$$('.close-dialog').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$('#play-film').addEventListener('click',()=>{$('#film-dialog').showModal();$('#film-dialog video').play().catch(()=>{})});$('#film-dialog').addEventListener('close',()=>$('#film-dialog video').pause());
$('#open-brief').addEventListener('click',()=>$('#brief-dialog').showModal());$('#brief-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);$('#prepared-message').value=`Hi In-Sight! I'm ${data.get('name')}.\n\nI'd love to discuss photography / films for a ${data.get('occasion').toLowerCase()}.${data.get('date')?`\nEvent date: ${data.get('date')}`:''}\n\n${data.get('details')}\n\nCould you share your availability and details?`;$('#brief-form').hidden=true;$('#brief-result').hidden=false;$('#prepared-message').focus()});$('#copy-message').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#prepared-message').value);$('#copy-status').textContent='Copied! Open Instagram and paste your message into a DM to @insightpinsta.'}catch{$('#prepared-message').select();$('#copy-status').textContent='Select and copy the message above, then send it to @insightpinsta on Instagram.'}});
